        if (ok('w6_flags') && i % 2 === 0) ctx.drawImage(I.w6_flags, bx - 70, wyp + 14);
        if (ok('w6_seal') && i % 2 === 0) ctx.drawImage(I.w6_seal, bx - 20, wyp + 6);
