        ctx.fillStyle = '#6a3e1e'; ctx.fillRect(leftLeaf ? X + 2 : X, Y, leftLeaf ? 14 : 14, 16);
        ctx.fillStyle = '#8a5a34'; ctx.fillRect(leftLeaf ? X + 4 : X + 2, Y + 2, 10, 12);
        ctx.fillStyle = '#a8743c'; ctx.fillRect(leftLeaf ? X + 4 : X + 2, Y + 2, 10, 1);
        ctx.fillStyle = '#4a2810'; ctx.fillRect(leftLeaf ? X + 4 : X + 2, Y + 7, 10, 1);
        if (topRow) { ctx.fillStyle = '#f6c680'; ctx.fillRect(X, Y, 16, 1); }
        if ((ty === 13 || ty === 14)) { ctx.fillStyle = '#e8c060'; ctx.fillRect(leftLeaf ? X + 13 : X + 2, Y + (ty === 13 ? 8 : 0), 2, 8); ctx.fillStyle = '#fff2b0'; ctx.fillRect(leftLeaf ? X + 13 : X + 2, Y + (ty === 13 ? 8 : 0), 1, 8); }
        if (ty === 6 && leftLeaf) { ctx.fillStyle = '#1a1008'; ctx.fillRect(X + 4, Y + 4, 28, 9); DD.text('NEXT', X + 18, Y + 6, '#f4eedc', 1, null, 'center'); }
