      const w = s.w, R = s.R && s.R[s.r];
      DD.text(w && w.shield > 0 ? 'STOMP THE FIFTH: ' + w.shield : (w && w.afraid ? 'HE BOLTS' : 'ANSWER THE QUESTION'), 8, 36, w && w.shield > 0 ? '#ffe680' : '#cfc6bc', 1, null);
