// ---- the process server (the Trial): a man in a trench coat with an envelope. He paces; when you come near he holds the papers up
// (a 30 frame warning, flashing "!"), then runs at you to serve them, then bends over wheezing (harmless). Stomp him any time for popcorn.
;(function () {
  const TS = 16;
  DD.defineEntity('procserver', {
    spawn: t => ({ x: t.x + 1, y: t.y - 2, w: 14, h: 34, vx: 0, vy: 0, x0: t.x, st: 'walk', t: 0, face: -1, a: 0 }),
    update(e, G) {
      e.a++; e.t++;
      const p = G.pl, edge = d => !DD.T(Math.floor((d > 0 ? e.x + e.w + 3 : e.x - 3) / TS), Math.floor((e.y + e.h + 3) / TS));
      if (e.st === 'walk') {
        if (edge(e.face) || DD.moveX(e, e.face * 0.45, false) || (Math.abs(e.x - e.x0) > 56 && (e.x - e.x0) * e.face > 0)) e.face = -e.face;
        const dx = DD.cx(p) - DD.cx(e), dy = (p.y + p.h) - (e.y + e.h);
        if (e.t > 30 && Math.abs(dx) < 120 && Math.abs(dx) > 16 && Math.abs(dy) < 24 && !G.fall) { e.st = 'spot'; e.t = 0; e.face = dx > 0 ? 1 : -1; DD.SFX.wind && DD.SFX.wind(); }
      } else if (e.st === 'spot') {
        if (e.t >= 30) { e.st = 'serve'; e.t = 0; }
      } else if (e.st === 'serve') {
        if (edge(e.face) || DD.moveX(e, e.face * 1.7, false) || e.t >= 36) { e.st = 'wheeze'; e.t = 0; DD.dust && DD.dust(DD.cx(e), e.y + e.h, 3, 1, '#d8b878'); }
      } else if (e.st === 'wheeze' && e.t >= 55) { e.st = 'walk'; e.t = 0; e.face = -e.face; }
      e.vy = Math.min(e.vy + 0.4, 6); if (DD.moveY(e, e.vy, false)) e.vy = 0;
      if (e.y > DD.L.H * TS + 40) e.dead = true;
    },
    draw(e, ctx) {
      const X = Math.round(DD.wx(e.x + e.w / 2)), Y = Math.round(DD.wy(e.y + e.h));
      const step = (e.st === 'walk' || e.st === 'serve') && Math.floor(e.a / (e.st === 'serve' ? 4 : 7)) % 2;
      ctx.fillStyle = 'rgba(0,0,0,0.3)'; ctx.beginPath(); ctx.ellipse(X, Y, 8, 2, 0, 0, 7); ctx.fill();
      DD.spr('w6_procserver_' + (e.st === 'spot' ? 2 : e.st === 'serve' ? 3 : e.st === 'wheeze' ? 4 : step ? 1 : 0), X, Y, e.face > 0);
      if (e.st === 'spot' && (e.t >> 2) % 2) DD.text('!', X + e.face * 14, Y - 36, '#ff5a40', 1, '#000', 'center');   // the warning flash
    },
    stomp(e, G) {
      e.dead = true; DD.addGot(3, DD.cx(e), e.y); DD.SFX.stomp && DD.SFX.stomp(); DD.stars(DD.cx(e), e.y, 6, '#f4f0e0');
      DD.part && DD.part({ x: DD.cx(e), y: e.y + 2, vx: e.face * 1.2, vy: -3, life: 40, max: 40, r: 3, col: '#f4f0e0', g: 0.25 });
      return true;
    },
    touch(e) { if (e.st === 'walk' || e.st === 'serve') DD.hurt(DD.cx(e)); },
  });
})();

// ---- the optional challenge room. LEVEL.CHALLENGE (from the .py): x0 = the wall column, door = the doorway in the secret [tile col, feet row],
